class FileHandler : public Handler {
private:
    string filePath;

public:
    FileHandler(string filePath) : filePath(filePath) {}

    void handle(const LogRecord& record) override {
        ofstream out(filePath, ios::app);
        if (!out) {
            throw runtime_error("Unable to open log file: " + filePath);
        }
        out << record.getFormatted() << "\n";
    }
